<script setup>import{ref,watch,onMounted}from'vue';import{useRoute,useRouter}from'vue-router';import api from'../services/api.js';import GuideCard from'../components/GuideCard.vue';import DestinationCard from'../components/DestinationCard.vue';import{useAuthStore}from'../stores/auth.js';const route=useRoute(),router=useRouter(),auth=useAuthStore(),keyword=ref(route.query.keyword||''),data=ref(null),loading=ref(false);const load=async()=>{if(!keyword.value.trim())return;loading.value=true;data.value=await api.get('/public/search',{params:{keyword:keyword.value}});if(auth.loggedIn)api.post('/user/search-history',{keyword:keyword.value}).catch(()=>{});loading.value=false};const submit=()=>router.push({path:'/search',query:{keyword:keyword.value}});watch(()=>route.query.keyword,v=>{keyword.value=v||'';load()});onMounted(load)</script>
<template><section class="search-head"><div class="container"><span>SEARCH THE JOURNEY</span><h1>搜索旅行灵感</h1><div><el-input v-model="keyword" size="large" placeholder="输入目的地、攻略、路线或专题" @keyup.enter="submit"/><el-button type="primary" size="large" @click="submit">搜索</el-button></div><p>热门：成都三天两夜 · 大理环洱海 · 学生党厦门 · 苏州周末游</p></div></section><div v-loading="loading" class="container search-results" v-if="data"><section><h2>攻略 <small>{{data.guides?.total}}</small></h2><div class="guide-grid"><GuideCard v-for="g in data.guides?.records" :key="g.id" :guide="g"/></div></section><section><h2>目的地 <small>{{data.destinations?.length}}</small></h2><div class="destination-grid"><DestinationCard v-for="d in data.destinations?.slice(0,8)" :key="d.id" :item="d"/></div></section><section><h2>路线与专题</h2><div class="simple-results"><router-link v-for="r in data.routes" :key="`r${r.id}`" :to="`/route/${r.id}`"><b>路线</b><span>{{r.name}}</span></router-link><router-link v-for="t in data.topics" :key="`t${t.id}`" :to="`/topic/${t.id}`"><b>专题</b><span>{{t.name}}</span></router-link></div></section></div></template>
<style scoped>.search-head{background:#153f47;padding:70px 0;color:white;text-align:center}.search-head>div>span{font-size:10px;letter-spacing:4px;color:#88d2d6}.search-head h1{font:42px Georgia,"Songti SC",serif}.search-head>div>div{max-width:720px;margin:25px auto 12px;display:flex;gap:10px}.search-head p{font-size:11px;color:#87aaaf}.search-results{padding:50px 0 90px}.search-results section{margin-bottom:65px}.search-results h2{font:30px Georgia,"Songti SC",serif}.search-results h2 small{color:#98a8aa}.destination-grid :deep(.destination-card){grid-column:auto;height:300px}.simple-results{display:grid;grid-template-columns:repeat(2,1fr);gap:10px}.simple-results a{background:white;border:1px solid #dae6e5;padding:18px;border-radius:12px}.simple-results b{font-size:11px;color:#167c8c;margin-right:12px}@media(max-width:600px){.simple-results{grid-template-columns:1fr}}</style>

